InterfaceAsPlainText.xhtml:
// lang-matrix: ST
PROGRAM PRG_LangSt
VAR
    xA : BOOL;
    xB : BOOL;
    xQ : BOOL;
    xDone : BOOL;
    iLevel : INT;
    xHigh : BOOL;
    wCode : WORD;
    sHex : STRING;
    fbTon : TON;
    fbHyst : HYSTERESIS;
END_VAR

ST.xhtml:
// Standard: TON; Util: HYSTERESIS; блок под замену: OSU.WORD_TO_HEX_STR (OwenStringUtils)
xQ := xA AND xB;
fbTon(IN := xQ, PT := T#100MS);
xDone := fbTon.Q;
fbHyst(IN := iLevel, HIGH := 80, LOW := 20, OUT => xHigh);
sHex := OSU.WORD_TO_HEX_STR(wInput := wCode, xUpperCase := TRUE, sPrefix := '0x');

